proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let a1 = always(always(p));
    let a2 = always(p);

    // Prove a1.entails(a2)
    assert(a1.entails(a2));
    {
        // a1.satisfied_by(ex)  ==>  a2.satisfied_by(ex)
        forall |ex: Execution<T>| {
            if a1.satisfied_by(ex) {
                assert(a2.satisfied_by(ex));
            }
        }
    }

    // Prove a2.entails(a1)
    assert(a2.entails(a1));
    {
        // a2.satisfied_by(ex)  ==>  a1.satisfied_by(ex)
        forall |ex: Execution<T>| {
            if a2.satisfied_by(ex) {
                assert(a1.satisfied_by(ex));
            }
        }
    }

    temp_pred_equality::<T>(a1, a2);
    assert(a1 == a2);
}

