                    // Pick j = 0.
                    let ex0 = ex.suffix(0);
                    assert((always(p)).satisfied_by(ex0)) by {
                        // From forall j, get the case j = 0
                        assert((forall |j: nat| #[trigger] (always(p)).satisfied_by(ex.suffix(j)))
                            by {
                                reveal(a1.satisfied_by(ex));
                                // Now the definition should match the forall.
                            });
                        // Use the forall to get j=0
                        assert((always(p)).satisfied_by(ex.suffix(0)));
                    };

                    // Now expand always(p) on ex0 and use i = k
                    assert(p.satisfied_by(ex0.suffix(k))) by {
                        reveal((always(p)).satisfied_by(ex0));
                        // The revealed form is forall i, p.satisfied_by(ex0.suffix(i))
                        assert(p.satisfied_by(ex0.suffix(k)));
                    };
                }
            }
        };
    };

    // a2.entails(a1)
    assert(a2.entails(a1)) by {
        forall |ex: Execution<T>| {
            if a2.satisfied_by(ex) {
                // Need: always(always(p)).satisfied_by(ex)
                assert(forall |j: nat| #[trigger] (always(p)).satisfied_by(ex.suffix(j))) by {
                    reveal(a2.satisfied_by(ex));
                    // revealed: forall k, p.satisfied_by(ex.suffix(k))
                    // Now show: for each j, always(p) holds on ex.suffix(j)
                    forall |j: nat| {
                        assert((always(p)).satisfied_by(ex.suffix(j))) by {
                            reveal((always(p)).satisfied_by(ex.suffix(j)));
                            // This should become forall i, p.satisfied_by((ex.suffix(j)).suffix(i))
                            forall |i: nat| {
                                // from always(p) on ex, we have p.satisfied_by(ex.suffix(j+i))
                                assert(p.satisfied_by(ex.suffix(j + i)));
                            };
                        };
                    };
                };
            }
        };
    };

    temp_pred_equality::<T>(a1, a2);
    assert(a1 == a2);
}

