proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let a1 = always(always(p));
    let a2 = always(p);

    // Prove: a1.entails(a2)
    assert(a1.entails(a2)) by {
        // entails(self, other) == valid(self.implies(other))
        reveal(a1.entails(a2));
        // valid(x) == forall ex, x.satisfied_by(ex)
        forall |ex: Execution<T>| {
            // implies: a1.satisfied_by(ex) ==> a2.satisfied_by(ex)
            if a1.satisfied_by(ex) {
                // a1.satisfied_by(ex) == forall j, always(p).satisfied_by(ex.suffix(j))
                assert(forall |j: nat| #[trigger] (always(p)).satisfied_by(ex.suffix(j))) by {
                    reveal(a1.satisfied_by(ex));
                };

                // instantiate j=0
                assert((always(p)).satisfied_by(ex.suffix(0)));

                // show always(p).satisfied_by(ex)
                // ex.suffix(0) == ex
                execution_equality::<T>(ex.suffix(0), ex);
                assert(ex.suffix(0) == ex);
                assert((always(p)).satisfied_by(ex.suffix(0)));
                // rewrite using the equality of executions
                assert((always(p)).satisfied_by(ex));
            }
        };
    };

    // Prove: a2.entails(a1)
    assert(a2.entails(a1)) by {
        reveal(a2.entails(a1));
        forall |ex: Execution<T>| {
            if a2.satisfied_by(ex) {
                // a2.satisfied_by(ex) == forall i, p.satisfied_by(ex.suffix(i))
                assert(forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i))) by {
                    reveal(a2.satisfied_by(ex));
                };

                // Need: a1.satisfied_by(ex) == forall j, always(p).satisfied_by(ex.suffix(j))
                assert(forall |j: nat| #[trigger] (always(p)).satisfied_by(ex.suffix(j)));
                forall |j: nat| {
                    // always(p).satisfied_by(ex.suffix(j)) == forall i, p.satisfied_by((ex.suffix(j)).suffix(i))
                    assert(forall |i: nat| #[trigger] p.satisfied_by((ex.suffix(j)).suffix(i))) by {
                        reveal((always(p)).satisfied_by(ex.suffix(j)));
                    };

                    // Now show for each i, p.satisfied_by(ex.suffix(j+i)) instead
                    // by proving (ex.suffix(j)).suffix(i) == ex.suffix(j+i)
                    forall |i: nat| {
                        execution_equality::<T>((ex.suffix(j)).suffix(i), ex.suffix(j + i));
                        assert(p.satisfied_by((ex.suffix(j)).suffix(i)));
                        // rewrite to the argument we have from the outer forall
                        assert(p.satisfied_by(ex.suffix(j + i)));
                    };
                };
            }
        };
    };

    temp_pred_equality::<T>(a1, a2);
}

