    // Show a1.entails(a2)
    assert(a1.entails(a2)) by {
        // unfolds to: forall ex. a1.satisfied_by(ex) ==> a2.satisfied_by(ex)
        reveal(a1.entails(a2));
        forall |ex: Execution<T>| {
            if a1.satisfied_by(ex) {
                // Goal: a2.satisfied_by(ex)
                assert(a2.satisfied_by(ex)) by {
                    reveal(a2.satisfied_by(ex));
                    forall |k: nat| {
                        // From a1.satisfied_by(ex), get always(p).satisfied_by(ex.suffix(0))
                        assert((always(p)).satisfied_by(ex.suffix(0))) by {
                            reveal(a1.satisfied_by(ex));
                        };

                        // Unfold that instance
                        let ap0 = (always(p)).satisfied_by(ex.suffix(0));
                        reveal(ap0);

                        assert(p.satisfied_by((ex.suffix(0)).suffix(k))) by {
                            reveal(ap0);
                        };

                        // (ex.suffix(0)).suffix(k) = ex.suffix(k)
                        execution_equality::<T>((ex.suffix(0)).suffix(k), ex.suffix(k));
                        assert((ex.suffix(0)).suffix(k) == ex.suffix(k));

                        assert(p.satisfied_by(ex.suffix(k)));
                    }
                };
            }
        };
    };

    // Show a2.entails(a1)
    assert(a2.entails(a1)) by {
        reveal(a2.entails(a1));
        forall |ex: Execution<T>| {
            if a2.satisfied_by(ex) {
                // Goal: a1.satisfied_by(ex)
                assert(a1.satisfied_by(ex)) by {
                    reveal(a1.satisfied_by(ex));
                    forall |i: nat| {
                        // Need always(p).satisfied_by(ex.suffix(i))
                        assert((always(p)).satisfied_by(ex.suffix(i))) by {
                            let asi = (always(p)).satisfied_by(ex.suffix(i));
