                                    reveal(a2.satisfied_by(ex));
                                    // instantiate the forall with k = i+j
                                };
                            }
                        };
                    }
                };
            }
        };
    };

    temp_pred_equality::<T>(a1, a2);
    assert(a1 == a2);
}

