use vstd::prelude::*;

fn main() {}

verus!{

// File: defs.rs
pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {

    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }

}


#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {

    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred {
            pred: pred,
        }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }

}


pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}


// File: rules.rs
	#[verifier::external_body]
pub proof fn execution_equality<T>(ex1: Execution<T>, ex2: Execution<T>)
    requires forall |i: nat| #[trigger] (ex1.nat_to_state)(i) == (ex2.nat_to_state)(i),
    ensures ex1 == ex2,
	{
		unimplemented!()
	}

	#[verifier::external_body]
pub proof fn temp_pred_equality<T>(p: TempPred<T>, q: TempPred<T>)
    requires
        p.entails(q),
        q.entails(p),
    ensures p == q,
	{
		unimplemented!()
	}

proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let a1 = always(always(p));
    let a2 = always(p);

    // a1.entails(a2)
    assert(a1.entails(a2)) by {
        forall |ex: Execution<T>| {
            // entails is valid(implies), so this is exactly the implication
            assert(a1.implies(a2).satisfied_by(ex));
            if a1.satisfied_by(ex) {
                // From a1.satisfied_by(ex): forall i, always(p).satisfied_by(ex.suffix(i))
                assert(always(p).satisfied_by(ex.suffix(0)));

                // a2.satisfied_by(ex): forall k, p.satisfied_by(ex.suffix(k))
                forall |k: nat| {
                    // always(p).satisfied_by(ex.suffix(0)) gives p.satisfied_by(ex.suffix(0).suffix(k))
                    assert(p.satisfied_by(ex.suffix(0).suffix(k)));

                    // Show ex.suffix(0).suffix(k) == ex.suffix(k)
                    execution_equality::<T>(ex.suffix(0).suffix(k), ex.suffix(k));
                    assert(ex.suffix(0).suffix(k) == ex.suffix(k));

                    assert(p.satisfied_by(ex.suffix(k)));
                }
            }
        }
    };

    // a2.entails(a1)
    assert(a2.entails(a1)) by {
        forall |ex: Execution<T>| {
            assert(a2.implies(a1).satisfied_by(ex));
            if a2.satisfied_by(ex) {
                // a1.satisfied_by(ex): forall i, always(p).satisfied_by(ex.suffix(i))
                forall |i: nat| {
                    // Need always(p).satisfied_by(ex.suffix(i))
                    forall |j: nat| {
                        // From a2.satisfied_by(ex): p.satisfied_by(ex.suffix(i+j))
                        assert(p.satisfied_by(ex.suffix(i + j)));

                        // always(p) expects p.satisfied_by((ex.suffix(i)).suffix(j))
                        execution_equality::<T>(
                            ex.suffix(i).suffix(j),
                            ex.suffix(i + j),
                        );
                        assert(ex.suffix(i).suffix(j) == ex.suffix(i + j));
                        assert(p.satisfied_by(ex.suffix(i).suffix(j)));
                    }

                    assert(always(p).satisfied_by(ex.suffix(i)));
                }
            }
        }
    };

    temp_pred_equality::<T>(a1, a2);
    assert(a1 == a2);
}


}

